    private Context context;private String prefix;private NativeJournal journal;private DeviceIdentity identity;private NativeClockSource clock;private NativeStaffUnlock unlock;private SecureSessionStore store;private NativeSession session;private NativeOfflineCoordinator offline;private NativeClockRecovery recovery;
    private String actor=id(),org=id(),branch=id(),device=id(),epoch=id(),shift=id();private JSONObject deviceIdentity;private OfflineBundle.Binding binding;private KeyPair server;private CookieHandler prior;
    private long wall=1_792_132_200_000L,elapsed=1000,serverTime=1_792_132_200_000L;private int boot=5;private final List<JSONObject> requests=new ArrayList<>();private final List<String> cookies=new ArrayList<>();private JSONObject accepted,lastTime;private int approves,lookups;private boolean lost,beforeFailure,badApproval,badTime;private Runnable during,duringLookup;
