    private String alias(String kind){return "internext.pos.test."+prefix+"."+kind;}
    private void reopen()throws Exception{if(offline!=null)offline.close();store=new SecureSessionStore(context,prefix+".bin",alias("session"));session=new NativeSession(store,new NativePosHttp(store,Fake::new),journal);clock=new NativeClockSource(context,journal,prefix+"-clock.db",alias("clock"),()->new NativeClockSource.Observation(boot,elapsed,wall));unlock=new NativeStaffUnlock(context,journal,clock,prefix+"-pin.db",alias("pin"),NativeStaffUnlock.mainScheduler(),()->elapsed);offline=new NativeOfflineCoordinator(journal,session,identity,clock,unlock,Collections.singletonMap("synthetic-server",server.getPublic()));recovery=new NativeClockRecovery(journal,session,offline);}
    @After public void cleanup()throws Exception{try{if(offline!=null)offline.close();if(journal!=null)journal.close();}finally{CookieHandler.setDefault(prior);for(String kind:new String[]{"ledger","clock","pin"})context.deleteDatabase(prefix+"-"+kind+".db");for(String suffix:new String[]{"",".bak",".new"})new File(context.getNoBackupFilesDir(),prefix+".bin"+suffix).delete();KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);for(String kind:new String[]{"identity","session","clock","pin"})ks.deleteEntry(alias(kind));}}
    private SQLiteDatabase auth()throws Exception{java.lang.reflect.Field f=NativeStaffUnlock.class.getDeclaredField("store");f.setAccessible(true);return((SQLiteOpenHelper)f.get(unlock)).getWritableDatabase();}
    private long count(String table)throws Exception{try(Cursor c=auth().rawQuery("SELECT count(*) FROM "+table,null)){c.moveToFirst();return c.getLong(0);}}
    private String rows(SQLiteDatabase db,String table){JSONArray a=new JSONArray();try(Cursor c=db.rawQuery("SELECT * FROM "+table+" ORDER BY rowid",null)){while(c.moveToNext()){JSONArray r=new JSONArray();for(int i=0;i<c.getColumnCount();i++)r.put(c.getString(i));a.put(r);}}return a.toString();}
    private interface Task{void run()throws Exception;}
    private static Exception fails(Task t)throws Exception{try{t.run();fail("Expected rejection");return null;}catch(AssertionError e){throw e;}catch(Exception e){return e;}}
    private JSONObject start()throws Exception{return recovery.startWithPassword(PASSWORD.toCharArray());}
    private String pending()throws Exception{fault();beforeFailure=true;fails(()->start());return recovery.getState().getString("requestId");}
    private JSONObject requestPayload(JSONObject envelope)throws Exception{return(JSONObject)SignedProtocol.verify(envelope.toString(),Collections.singletonMap(deviceIdentity.getString("deviceKeySha256"),SignedProtocol.publicKey(SignedProtocol.decode(deviceIdentity.getString("publicKeySpkiBase64Url"),256)))).payload();}
    private JSONObject approval(JSONObject proof)throws Exception{JSONObject payload=requestPayload(proof);JSONObject out=NativeClockRecoveryProof.core(payload).put("kind","native-clock-recovery-approval").put("schemaVersion",1).put("proofSha256",NativeClockRecoveryProof.payloadHash(proof.toString())).put("approvedAt",NativeCheckoutEngine.iso(wall));if(badApproval)out.put("actorId",id());return new JSONObject(SignedProtocol.sign(out,"synthetic-server",server.getPrivate(),server.getPublic()));}
    private JSONObject access()throws Exception{return new JSONObject().put("schemaVersion",1).put("status","signed_in").put("actorId",actor).put("canPrepareOffline",false).put("device",new JSONObject().put("id",device).put("branchId",branch).put("name","Synthetic counter")).put("branches",new JSONArray().put(new JSONObject().put("id",branch).put("organizationId",org).put("name","Synthetic branch").put("role","manager")));}

    private SQLiteDatabase clockDb()throws Exception{java.lang.reflect.Field f=NativeClockSource.class.getDeclaredField("store");f.setAccessible(true);return((SQLiteOpenHelper)f.get(clock)).getWritableDatabase();}
    private void fault()throws Exception{clock.read();wall--;assertEquals("ready",recovery.getState().getString("status"));wall=serverTime;elapsed++;}
    private String text(String query){try(Cursor c=journal.getReadableDatabase().rawQuery(query,null)){assertTrue(c.moveToFirst());return c.getString(0);}}
    private PublicKey publicKey()throws Exception{return SignedProtocol.publicKey(SignedProtocol.decode(deviceIdentity.getString("publicKeySpkiBase64Url"),256));}
    private Map<String,PublicKey> keys(){return Collections.singletonMap("synthetic-server",server.getPublic());}
    private JSONObject time(JSONObject body)throws Exception{JSONObject p=requestPayload(body.getJSONObject("proof"));JSONObject t=new JSONObject().put("kind","native-clock-recovery-time").put("schemaVersion",1).put("requestId",p.get("requestId")).put("approvalSha256",NativeClockRecoveryProof.payloadHash(accepted.toString())).put("retirementSha256",p.get("retirementSha256")).put("oldClockGeneration",p.get("oldClockGeneration")).put("challenge",badTime?String.join("",Collections.nCopies(64,"f")):body.get("challenge")).put("serverTimeMs",serverTime);return new JSONObject(SignedProtocol.sign(t,"synthetic-server",server.getPrivate(),server.getPublic()));}
    private void install()throws Exception{
        ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=InstrumentationRegistry.getInstrumentation().getContext().getAssets().open("pos-offline-output.json")){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);}
        JSONObject fixture=new JSONObject(bytes.toString("UTF-8")).getJSONObject("reservation");snapshot=fixture.getJSONObject("snapshot");authority=fixture.getJSONObject("authority");
        for(JSONObject p:new JSONObject[]{snapshot,authority}){for(String k:new String[]{"organizationId","branchId","deviceId","actorId","shiftId","keyEpoch"})if(p.has(k))p.put(k,k.equals("organizationId")?org:k.equals("branchId")?branch:k.equals("deviceId")?device:k.equals("actorId")?actor:k.equals("shiftId")?shift:epoch);}
        // Snapshot scope intentionally has fewer fields than authority.
        for(String k:new String[]{"deviceId","actorId","shiftId","keyEpoch"})if(!fixture.getJSONObject("snapshot").has(k))snapshot.remove(k);
        authority.put("id",id()).put("deviceKeySha256",deviceIdentity.getString("deviceKeySha256")).put("issuedAt",NativeCheckoutEngine.iso(serverTime)).put("notBefore",NativeCheckoutEngine.iso(serverTime)).put("expiresAt",NativeCheckoutEngine.iso(serverTime+3600000));snapshot.put("createdAt",NativeCheckoutEngine.iso(serverTime));snapshot.getJSONObject("profile").put("organizationId",org).put("branchId",branch);
        rebuild();unlock.unlock(binding,OLD.toCharArray());engine=new NativeCheckoutEngine(journal,keys(),binding,publicKey(),unlock,clock,identity::sign);engine.installVerifiedBundle(snapshotEnvelope,authorityEnvelope,serverTime);
        JSONObject saved=store.read();saved.getJSONObject("offline").put("reservation",new JSONObject().put("requestId",authority.getString("id")).put("branchId",branch).put("deviceId",device).put("shiftId",shift).put("count",100).put("lifetimeSeconds",3600).put("maxInvoiceTotalFils",100000).put("maxGrossFils",10000000).put("permissions",new JSONObject().put("cash",true).put("recordedCard",true).put("mixedTender",true)));store.write(saved);
    }
    private void rebuild()throws Exception{authority.put("snapshotSha256",SignedProtocol.hash(CanonicalJson.bytes(snapshot)));snapshotEnvelope=SignedProtocol.sign(snapshot,"synthetic-server",server.getPrivate(),server.getPublic());authorityEnvelope=SignedProtocol.sign(authority,"synthetic-server",server.getPrivate(),server.getPublic());}
    private JSONObject input()throws Exception{return new JSONObject().put("authorityId",authority.getString("id")).put("serviceType","takeaway").put("customer",JSONObject.NULL).put("lines",new JSONArray().put(new JSONObject().put("productId",snapshot.getJSONArray("products").getJSONObject(0).getString("id")).put("quantityMilli",1000))).put("cashTenderedFils",1000).put("recordedCardFils",0).put("presentedTotalFils",1000);}
