    private final class Fake extends HttpsURLConnection{
        private final ByteArrayOutputStream out=new ByteArrayOutputStream();private byte[] response;private boolean drop;
        Fake(URL url){super(url);}
        @Override public int getResponseCode()throws IOException{try{
            if(url.getPath().equals("/api/pos/native/access")){response=access().toString().getBytes(StandardCharsets.UTF_8);return 200;}
            assertEquals("/api/pos/native/clock-recovery",url.getPath());JSONObject body=new JSONObject(out.toString("UTF-8"));requests.add(body);cookies.add(getRequestProperty("Cookie"));String mode=body.getString("mode");JSONObject proof=body.getJSONObject("proof");requestPayload(proof);
            if(mode.equals("lookup")){lookups++;assertNull(getRequestProperty("Cookie"));if(duringLookup!=null){Runnable r=duringLookup;duringLookup=null;r.run();}if(accepted==null){response=new JSONObject().put("status","not_found").toString().getBytes(StandardCharsets.UTF_8);return 200;}}
            else{approves++;assertNotNull(getRequestProperty("Cookie"));assertEquals(PASSWORD,body.getString("password"));assertNotNull(clock.recoveryPending());if(beforeFailure){beforeFailure=false;throw new IOException("Synthetic before approval");}if(accepted==null)accepted=approval(proof);drop=lost;lost=false;}
            lastTime=time(body);response=new JSONObject().put("status","approved").put("approval",accepted).put("time",lastTime).toString().getBytes(StandardCharsets.UTF_8);if(during!=null){Runnable r=during;during=null;r.run();}return 200;
        }catch(IOException e){throw e;}catch(Exception e){throw new IOException("Synthetic fixture",e);}}
        @Override public Map<String,List<String>> getHeaderFields(){return Collections.singletonMap("Set-Cookie",Collections.singletonList("pos-access=synthetic-rotated; Secure; HttpOnly; Path=/"));}
        @Override public String getContentType(){return "application/json";}@Override public String getHeaderField(String name){return null;}@Override public long getContentLengthLong(){return -1;}@Override public InputStream getInputStream()throws IOException{if(drop)throw new IOException("Synthetic lost reply");return new ByteArrayInputStream(response);}@Override public InputStream getErrorStream(){return new ByteArrayInputStream(response);}@Override public OutputStream getOutputStream(){return out;}@Override public void disconnect(){}@Override public boolean usingProxy(){return false;}@Override public void connect(){}@Override public String getCipherSuite(){return "TLS_SYNTHETIC";}@Override public Certificate[] getLocalCertificates(){return null;}@Override public Certificate[] getServerCertificates(){return new Certificate[0];}
    }
